package com.fasterxml.jackson.databind.ext;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.json.JsonMapper;
import org.junit.Test;
import javax.xml.namespace.QName;
import static org.junit.Assert.*;

public class CoreXMLDeserializersQNameTest {

    @Test
    public void testDeserializeEmptyStringToQName() throws Exception {
        ObjectMapper mapper = JsonMapper.builder().build();

        // Deserialize empty JSON string to QName
        QName result = mapper.readValue("\"\"", QName.class);

        // Before patch: result would be null
        // After patch: result should be an empty QName
        assertNotNull("QName should not be null", result);
        assertTrue("QName local part should be empty", result.getLocalPart().isEmpty());
        // Also verify it's the same as QName.valueOf("")
        assertEquals(QName.valueOf(""), result);
    }

    @Test
    public void testDeserializeNonEmptyStringToQName() throws Exception {
        ObjectMapper mapper = JsonMapper.builder().build();

        // Ensure normal QName deserialization still works
        QName result = mapper.readValue("\"localPart\"", QName.class);
        assertNotNull(result);
        assertEquals("localPart", result.getLocalPart());

        // Test with namespace
        result = mapper.readValue("\"{namespace}localPart\"", QName.class);
        assertNotNull(result);
        assertEquals("namespace", result.getNamespaceURI());
        assertEquals("localPart", result.getLocalPart());
    }

    @Test
    public void testDeserializeEmptyStringWithCoercionConfig() throws Exception {
        // Test with different coercion configurations
        ObjectMapper mapper = JsonMapper.builder()
                .disable(com.fasterxml.jackson.databind.MapperFeature.ALLOW_COERCION_OF_SCALARS)
                .build();

        // Even with coercion disabled, empty QName should still work
        // (the patch ensures empty QName is returned regardless of coercion action)
        QName result = mapper.readValue("\"\"", QName.class);
        assertNotNull(result);
        assertTrue(result.getLocalPart().isEmpty());
    }
}

