package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonAnyGetter;
import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class ThrowableDeserializerTest {

    static class Problem extends Exception {
        @JsonAnySetter
        @JsonAnyGetter
        Map<String, Object> additionalProperties = new HashMap<>();

        // Default constructor
        public Problem() {
            super();
        }

        // Constructor with message
        public Problem(String message) {
            super(message);
        }
    }

    @Test
    public void testDeserializeThrowableWithAnySetter() throws JsonProcessingException {
        // Create a Problem instance with some additional properties
        Problem problem = new Problem("test message");
        problem.additionalProperties.put("additional", "additional");
        problem.additionalProperties.put("extra", 123);

        ObjectMapper mapper = new ObjectMapper();

        // Serialize
        String json = mapper.writeValueAsString(problem);

        // Deserialize - this should NOT throw NullPointerException after the patch
        Problem result = mapper.readValue(json, Problem.class);

        // Verify the deserialized object
        assertNotNull(result);
        assertEquals("test message", result.getMessage());
        assertNotNull(result.additionalProperties);
        assertEquals(2, result.additionalProperties.size());
        assertEquals("additional", result.additionalProperties.get("additional"));
        assertEquals(123, result.additionalProperties.get("extra"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterAndNoMessage() throws JsonProcessingException {
        // Create a Problem instance without a message but with additional properties
        Problem problem = new Problem();
        problem.additionalProperties.put("key", "value");

        ObjectMapper mapper = new ObjectMapper();

        // Serialize
        String json = mapper.writeValueAsString(problem);

        // Deserialize - this should also NOT throw NullPointerException after the patch
        Problem result = mapper.readValue(json, Problem.class);

        // Verify the deserialized object
        assertNotNull(result);
        assertNull(result.getMessage());
        assertNotNull(result.additionalProperties);
        assertEquals(1, result.additionalProperties.size());
        assertEquals("value", result.additionalProperties.get("key"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterAndEmptyMessage() throws JsonProcessingException {
        // Create a Problem instance with empty message and additional properties
        Problem problem = new Problem("");
        problem.additionalProperties.put("empty", true);

        ObjectMapper mapper = new ObjectMapper();

        // Serialize
        String json = mapper.writeValueAsString(problem);

        // Deserialize
        Problem result = mapper.readValue(json, Problem.class);

        // Verify the deserialized object
        assertNotNull(result);
        assertEquals("", result.getMessage());
        assertNotNull(result.additionalProperties);
        assertEquals(1, result.additionalProperties.size());
        assertEquals(true, result.additionalProperties.get("empty"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterAndMultipleProperties() throws JsonProcessingException {
        // Create JSON with message and additional properties
        String json = "{\"message\":\"error occurred\",\"custom1\":\"value1\",\"custom2\":42}";

        ObjectMapper mapper = new ObjectMapper();

        // Deserialize - this should work after the patch
        Problem result = mapper.readValue(json, Problem.class);

        // Verify the deserialized object
        assertNotNull(result);
        assertEquals("error occurred", result.getMessage());
        assertNotNull(result.additionalProperties);
        assertEquals(2, result.additionalProperties.size());
        assertEquals("value1", result.additionalProperties.get("custom1"));
        assertEquals(42, result.additionalProperties.get("custom2"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterAndSuppressedField() throws JsonProcessingException {
        // Create JSON with suppressed field and additional properties
        String json = "{\"message\":\"test\",\"suppressed\":[],\"extra\":\"data\"}";

        ObjectMapper mapper = new ObjectMapper();

        // Deserialize - this should work after the patch
        Problem result = mapper.readValue(json, Problem.class);

        // Verify the deserialized object
        assertNotNull(result);
        assertEquals("test", result.getMessage());
        assertNotNull(result.additionalProperties);
        assertEquals(1, result.additionalProperties.size());
        assertEquals("data", result.additionalProperties.get("extra"));
    }
}

