package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNodeWithObjectTest {

    private final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    public void testWithObjectWithPropertyName() {
        // This test should fail before the patch and pass after.
        // Before patch: withObject("property") would try to compile as JsonPointer and throw.
        // After patch: it should treat "property" as a property name and create an object node.

        ObjectNode root = MAPPER.createObjectNode();
        ObjectNode child = root.withObject("property");
        assertNotNull(child);
        assertTrue(child.isObject());
        // The child should be added to the root
        assertSame(child, root.get("property"));
    }

    @Test
    public void testWithObjectWithJsonPointer() {
        // This test should pass both before and after patch, but we include for completeness.
        // Using a JsonPointer expression.
        ObjectNode root = MAPPER.createObjectNode();
        ObjectNode child = root.withObject("/foo/bar");
        assertNotNull(child);
        assertTrue(child.isObject());
        // The structure should be created: root -> foo -> bar
        JsonNode foo = root.get("foo");
        assertNotNull(foo);
        assertTrue(foo.isObject());
        JsonNode bar = foo.get("bar");
        assertNotNull(bar);
        assertSame(child, bar);
    }

    @Test
    public void testWithObjectWithEmptyString() {
        // Empty string is a valid JsonPointer (points to root).
        // This should work as a JsonPointer.
        ObjectNode root = MAPPER.createObjectNode();
        ObjectNode child = root.withObject("");
        // The empty JsonPointer should return the root itself.
        assertSame(root, child);
    }

    @Test
    public void testWithObjectWithNestedProperty() {
        // Test with a property name that contains a slash but does not start with slash.
        // This should be treated as a property name, not a JsonPointer.
        ObjectNode root = MAPPER.createObjectNode();
        ObjectNode child = root.withObject("a/b");
        assertNotNull(child);
        assertTrue(child.isObject());
        // The property name is "a/b", so root should have a key "a/b"
        assertSame(child, root.get("a/b"));
    }

    @Test
    public void testWithObjectWithLeadingSlashProperty() {
        // A string starting with '/' is a JsonPointer.
        ObjectNode root = MAPPER.createObjectNode();
        ObjectNode child = root.withObject("/x");
        assertNotNull(child);
        assertTrue(child.isObject());
        // Should create a nested object at path "/x"
        assertSame(child, root.get("x"));
    }

    @Test
    public void testWithObjectWithMultipleSlashes() {
        // A more complex JsonPointer.
        ObjectNode root = MAPPER.createObjectNode();
        ObjectNode child = root.withObject("/a/b/c");
        assertNotNull(child);
        assertTrue(child.isObject());
        // Verify the structure.
        JsonNode a = root.get("a");
        assertNotNull(a);
        assertTrue(a.isObject());
        JsonNode b = a.get("b");
        assertNotNull(b);
        assertTrue(b.isObject());
        JsonNode c = b.get("c");
        assertNotNull(c);
        assertSame(child, c);
    }
}

