package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.node.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonNodeWithObjectArrayPropertyTest {

    @Test
    public void testWithObjectPropertyOnObjectNode() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Case 1: Property doesn't exist - should create new ObjectNode
        ObjectNode child1 = root.withObjectProperty("newObject");
        assertNotNull(child1);
        assertTrue(child1.isObject());
        assertSame(child1, root.get("newObject"));

        // Case 2: Property exists and is ObjectNode - should return existing
        ObjectNode child2 = root.withObjectProperty("newObject");
        assertSame(child1, child2);

        // Case 3: Property exists and is NullNode - should create new ObjectNode
        root.putNull("nullProp");
        ObjectNode child3 = root.withObjectProperty("nullProp");
        assertNotNull(child3);
        assertTrue(child3.isObject());
        assertSame(child3, root.get("nullProp"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnNonObjectNode() {
        // This should fail on base JsonNode implementation
        JsonNode arrayNode = JsonNodeFactory.instance.arrayNode();
        arrayNode.withObjectProperty("prop");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnWrongNodeType() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        root.put("textProp", "value");

        // This should throw because property exists as TextNode, not ObjectNode
        root.withObjectProperty("textProp");
    }

    @Test
    public void testWithArrayPropertyOnObjectNode() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Case 1: Property doesn't exist - should create new ArrayNode
        ArrayNode child1 = root.withArrayProperty("newArray");
        assertNotNull(child1);
        assertTrue(child1.isArray());
        assertSame(child1, root.get("newArray"));

        // Case 2: Property exists and is ArrayNode - should return existing
        ArrayNode child2 = root.withArrayProperty("newArray");
        assertSame(child1, child2);

        // Case 3: Property exists and is NullNode - should create new ArrayNode
        root.putNull("nullArray");
        ArrayNode child3 = root.withArrayProperty("nullArray");
        assertNotNull(child3);
        assertTrue(child3.isArray());
        assertSame(child3, root.get("nullArray"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyOnNonObjectNode() {
        // This should fail on base JsonNode implementation
        JsonNode textNode = JsonNodeFactory.instance.textNode("test");
        textNode.withArrayProperty("prop");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyOnWrongNodeType() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        root.put("objectProp", JsonNodeFactory.instance.objectNode());

        // This should throw because property exists as ObjectNode, not ArrayNode
        root.withArrayProperty("objectProp");
    }

    @Test
    public void testWithObjectPropertyChain() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Create nested structure using withObjectProperty
        ObjectNode level1 = root.withObjectProperty("level1");
        ObjectNode level2 = level1.withObjectProperty("level2");
        ObjectNode level3 = level2.withObjectProperty("level3");

        assertNotNull(level1);
        assertNotNull(level2);
        assertNotNull(level3);
        assertSame(level1, root.get("level1"));
        assertSame(level2, level1.get("level2"));
        assertSame(level3, level2.get("level3"));
    }

    @Test
    public void testWithArrayPropertyChain() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Create array and add elements
        ArrayNode array = root.withArrayProperty("items");
        array.add("item1");
        array.add("item2");

        // Get the same array and verify contents
        ArrayNode sameArray = root.withArrayProperty("items");
        assertEquals(2, sameArray.size());
        assertEquals("item1", sameArray.get(0).asText());
        assertEquals("item2", sameArray.get(1).asText());
    }

    @Test
    public void testMixedObjectAndArrayProperties() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Create both object and array properties
        ObjectNode obj = root.withObjectProperty("config");
        ArrayNode arr = root.withArrayProperty("list");

        assertTrue(obj.isObject());
        assertTrue(arr.isArray());
        assertSame(obj, root.get("config"));
        assertSame(arr, root.get("list"));

        // Add some data
        obj.put("enabled", true);
        arr.add(1);
        arr.add(2);

        // Verify data persists
        ObjectNode sameObj = root.withObjectProperty("config");
        assertTrue(sameObj.get("enabled").asBoolean());

        ArrayNode sameArr = root.withArrayProperty("list");
        assertEquals(2, sameArr.size());
        assertEquals(1, sameArr.get(0).asInt());
        assertEquals(2, sameArr.get(1).asInt());
    }
}

