import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNodeWithObjectPropertyTest {

    @Test
    public void testWithObjectPropertyOnObjectNodeWhenPropertyDoesNotExist() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Property does not exist - should create new ObjectNode
        ObjectNode child = root.withObjectProperty("newObject");
        assertNotNull(child);
        assertTrue(child.isObject());
        assertTrue(root.has("newObject"));
        assertSame(child, root.get("newObject"));
    }

    @Test
    public void testWithObjectPropertyOnObjectNodeWhenPropertyIsNull() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.putNull("nullProperty");

        // Property exists but is null - should create new ObjectNode
        ObjectNode child = root.withObjectProperty("nullProperty");
        assertNotNull(child);
        assertTrue(child.isObject());
        assertTrue(root.has("nullProperty"));
        assertSame(child, root.get("nullProperty"));
    }

    @Test
    public void testWithObjectPropertyOnObjectNodeWhenPropertyIsObjectNode() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        ObjectNode existingChild = mapper.createObjectNode();
        existingChild.put("existingField", "value");
        root.set("existingObject", existingChild);

        // Property exists and is ObjectNode - should return existing ObjectNode
        ObjectNode retrieved = root.withObjectProperty("existingObject");
        assertSame(existingChild, retrieved);
        assertEquals("value", retrieved.get("existingField").asText());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnNonObjectNode() {
        ObjectMapper mapper = new ObjectMapper();
        ArrayNode arrayNode = mapper.createArrayNode();

        // Should throw UnsupportedOperationException on non-ObjectNode
        arrayNode.withObjectProperty("property");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyWhenPropertyIsWrongType() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.put("textProperty", "some text");

        // Property exists but is TextNode - should throw exception
        root.withObjectProperty("textProperty");
    }

    @Test
    public void testWithObjectPropertyChain() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Test chaining withObjectProperty calls
        ObjectNode child1 = root.withObjectProperty("child1");
        ObjectNode child2 = child1.withObjectProperty("child2");
        ObjectNode child3 = child2.withObjectProperty("child3");

        assertTrue(root.has("child1"));
        assertSame(child1, root.get("child1"));
        assertTrue(child1.has("child2"));
        assertSame(child2, child1.get("child2"));
        assertTrue(child2.has("child3"));
        assertSame(child3, child2.get("child3"));
    }

    @Test
    public void testWithObjectPropertyOnEmptyObjectNode() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Multiple properties
        ObjectNode obj1 = root.withObjectProperty("obj1");
        ObjectNode obj2 = root.withObjectProperty("obj2");

        assertNotSame(obj1, obj2);
        assertEquals(2, root.size());
        assertTrue(root.has("obj1"));
        assertTrue(root.has("obj2"));
    }

    @Test
    public void testWithObjectPropertyReturnsMutableObject() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        ObjectNode child = root.withObjectProperty("child");
        child.put("newField", "newValue");

        // Verify the child is mutable and changes are reflected in parent
        assertEquals("newValue", root.get("child").get("newField").asText());
    }
}

