package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNodeWithArrayPropertyTest {

    @Test
    public void testWithArrayPropertyCreatesNewArrayWhenPropertyDoesNotExist() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode objectNode = mapper.createObjectNode();

        // Before patch: withArrayProperty doesn't exist, so this would fail to compile
        // After patch: should create new array and return it
        ArrayNode arrayNode = objectNode.withArrayProperty("newArray");

        assertNotNull(arrayNode);
        assertTrue(arrayNode.isArray());
        assertEquals(0, arrayNode.size());
        assertTrue(objectNode.has("newArray"));
        assertSame(arrayNode, objectNode.get("newArray"));
    }

    @Test
    public void testWithArrayPropertyCreatesNewArrayWhenPropertyIsNull() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode objectNode = mapper.createObjectNode();
        objectNode.putNull("nullArray");

        // Before patch: withArrayProperty doesn't exist, so this would fail to compile
        // After patch: should create new array and return it (replacing null)
        ArrayNode arrayNode = objectNode.withArrayProperty("nullArray");

        assertNotNull(arrayNode);
        assertTrue(arrayNode.isArray());
        assertEquals(0, arrayNode.size());
        assertTrue(objectNode.has("nullArray"));
        assertSame(arrayNode, objectNode.get("nullArray"));
    }

    @Test
    public void testWithArrayPropertyReturnsExistingArray() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode objectNode = mapper.createObjectNode();
        ArrayNode existingArray = objectNode.putArray("existingArray");
        existingArray.add("value1");

        // Before patch: withArrayProperty doesn't exist, so this would fail to compile
        // After patch: should return the existing array
        ArrayNode retrievedArray = objectNode.withArrayProperty("existingArray");

        assertSame(existingArray, retrievedArray);
        assertEquals(1, retrievedArray.size());
        assertEquals("value1", retrievedArray.get(0).asText());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyThrowsOnNonObjectNode() {
        ObjectMapper mapper = new ObjectMapper();
        ArrayNode arrayNode = mapper.createArrayNode();

        // Before patch: base implementation throws UnsupportedOperationException
        // After patch: same behavior - should still throw
        arrayNode.withArrayProperty("property");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyThrowsOnWrongNodeType() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode objectNode = mapper.createObjectNode();
        objectNode.put("textProperty", "not an array");

        // Before patch: withArrayProperty doesn't exist, so this would fail to compile
        // After patch: should throw UnsupportedOperationException because property is TextNode
        objectNode.withArrayProperty("textProperty");
    }

    @Test
    public void testWithArrayPropertyMultipleCalls() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode objectNode = mapper.createObjectNode();

        // First call creates array
        ArrayNode array1 = objectNode.withArrayProperty("multiArray");
        array1.add("first");

        // Second call returns same array
        ArrayNode array2 = objectNode.withArrayProperty("multiArray");
        array2.add("second");

        assertSame(array1, array2);
        assertEquals(2, array1.size());
        assertEquals("first", array1.get(0).asText());
        assertEquals("second", array1.get(1).asText());
    }

    @Test
    public void testWithArrayPropertyOnEmptyObjectNode() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode objectNode = mapper.createObjectNode();

        // Verify object starts empty
        assertEquals(0, objectNode.size());

        // Create array property
        ArrayNode arrayNode = objectNode.withArrayProperty("emptyArray");

        assertEquals(1, objectNode.size());
        assertTrue(objectNode.has("emptyArray"));
        assertSame(arrayNode, objectNode.get("emptyArray"));
    }

    @Test
    public void testWithArrayPropertyChain() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Create nested structure using withArrayProperty
        ArrayNode topArray = root.withArrayProperty("top");
        topArray.add("item1");

        // Add an object to the array
        ObjectNode nestedObject = topArray.addObject();
        ArrayNode nestedArray = nestedObject.withArrayProperty("nested");
        nestedArray.add("nestedItem");

        // Verify structure
        assertEquals(1, root.size());
        assertTrue(root.has("top"));
        assertEquals(2, topArray.size());
        assertEquals("item1", topArray.get(0).asText());
        assertTrue(topArray.get(1).isObject());

        ObjectNode retrievedObject = (ObjectNode) topArray.get(1);
        assertTrue(retrievedObject.has("nested"));
        ArrayNode retrievedArray = (ArrayNode) retrievedObject.get("nested");
        assertEquals(1, retrievedArray.size());
        assertEquals("nestedItem", retrievedArray.get(0).asText());
    }
}

