        ArrayNode topArray = root.withArrayProperty("top");
        topArray.add("item1");

        // Add an object to the array
        ObjectNode nestedObject = topArray.addObject();
        ArrayNode nestedArray = nestedObject.withArrayProperty("nested");
        nestedArray.add("nestedItem");

