        assertTrue(root.has("top"));
        assertEquals(2, topArray.size());
        assertEquals("item1", topArray.get(0).asText());
        assertTrue(topArray.get(1).isObject());

        ObjectNode retrievedObject = (ObjectNode) topArray.get(1);
        assertTrue(retrievedObject.has("nested"));
        ArrayNode retrievedArray = (ArrayNode) retrievedObject.get("nested");
        assertEquals(1, retrievedArray.size());
        assertEquals("nestedItem", retrievedArray.get(0).asText());
    }
