        // Before patch: checkUnsupportedType returns null for Optional types
        // After patch: returns error message
        String optionalResult = BeanUtil.checkUnsupportedType(optionalType);
        String optionalIntResult = BeanUtil.checkUnsupportedType(optionalIntType);
        String optionalLongResult = BeanUtil.checkUnsupportedType(optionalLongType);
        String optionalDoubleResult = BeanUtil.checkUnsupportedType(optionalDoubleType);

        // Assert that after patch, all Optional types are detected as unsupported
        // and return the appropriate error message
        assertNotNull("Optional should be detected as unsupported", optionalResult);
        assertNotNull("OptionalInt should be detected as unsupported", optionalIntResult);
        assertNotNull("OptionalLong should be detected as unsupported", optionalLongResult);
        assertNotNull("OptionalDouble should be detected as unsupported", optionalDoubleResult);

        // Verify the error message format
        assertTrue(optionalResult.contains("Java 8 optional"));
        assertTrue(optionalResult.contains("jackson-datatype-jdk8"));
        assertTrue(optionalIntResult.contains("Java 8 optional"));
        assertTrue(optionalIntResult.contains("jackson-datatype-jdk8"));

        // Test with non-optional types - should return null
        JavaType stringType = typeFactory.constructType(String.class);
