package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonIgnore;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.MapperFeature;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonIgnoreTransientFieldTest {

    static class TestBean {
        private String normal = "hello";
        private transient String transientField = "world";

        @JsonIgnore
        public String getTransientField() {
            return transientField;
        }

        public void setTransientField(String s) {
            this.transientField = s;
        }

        public String getNormal() {
            return normal;
        }

        public void setNormal(String s) {
            this.normal = s;
        }
    }

    @Test
    public void testTransientFieldWithJsonIgnore() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Ensure PROPAGATE_TRANSIENT_MARKER is disabled (default)
        mapper.disable(MapperFeature.PROPAGATE_TRANSIENT_MARKER);

        TestBean bean = new TestBean();
        bean.setNormal("foo");
        bean.setTransientField("bar");

        // Serialize: transient field with @JsonIgnore should not appear
        String json = mapper.writeValueAsString(bean);
        // The JSON should contain "normal" but not "transientField"
        assertTrue(json.contains("foo"));
        assertFalse(json.contains("bar"));
        assertFalse(json.contains("transientField"));

        // Deserialize: JSON without the field should leave transient field as null (or default)
        // We'll set it to something else first to see if it changes
        TestBean bean2 = mapper.readValue("{\"normal\":\"baz\"}", TestBean.class);
        assertEquals("baz", bean2.getNormal());
        // The transient field should be null because it's not set by constructor/setter
        // Actually, since we have a setter annotated with @JsonIgnore, it should not be set.
        // But the field is transient and ignored, so it should remain as default (null) after deserialization.
        // However, note: the field is initialized to "world" in the class, but because it's transient,
        // Java serialization would skip it. Jackson deserialization will not set it because of @JsonIgnore.
        // So we expect it to be null (since we didn't set it in the JSON and the setter is ignored).
        // But note: the field is initialized to "world" in the declaration. However, when we create a new instance
        // via Jackson, it uses the no-args constructor and then sets fields via setters or directly.
        // Since the setter is ignored, the field will not be set, so it should remain as the default value "world".
        // Wait: Actually, the field is transient and has a default value "world". When Jackson creates an instance,
        // it calls the default constructor, so the field will be "world". Then it sets properties from JSON.
        // Since the setter is ignored, the field stays as "world". So we should assert that it's "world".
        // But the issue is about the field being serialized. So for deserialization, we want to ensure that
        // if we have a JSON with the field, it is ignored. Let's test that.

        // Let's do a more comprehensive test:
        // 1. Serialization: field should not appear.
        // 2. Deserialization: if JSON has the field, it should be ignored.

        // For deserialization test, we'll create a JSON that includes the field and see if it's set.
        String jsonWithField = "{\"normal\":\"baz\",\"transientField\":\"shouldBeIgnored\"}";
        TestBean bean3 = mapper.readValue(jsonWithField, TestBean.class);
        assertEquals("baz", bean3.getNormal());
        // The transient field should be "world" (default) because the setter is ignored.
        // But note: the field is transient, so even without @JsonIgnore, Jackson might skip it?
        // Actually, without @JsonIgnore and with PROPAGATE_TRANSIENT_MARKER disabled, the field is skipped.
        // But with @JsonIgnore, it should be skipped regardless.
        // So we assert that it's "world" (the default from the constructor).
        assertEquals("world", bean3.getTransientField());
    }

    // Additional test: same but with a field that is transient and has @JsonIgnore on the field itself.
    static class TestBean2 {
        public String normal = "hello";
        @JsonIgnore
        private transient String def = "world";

        public String getDef() {
            return def;
        }

        public void setDef(String s) {
            this.def = s;
        }
    }

    @Test
    public void testTransientFieldWithJsonIgnoreOnField() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(MapperFeature.PROPAGATE_TRANSIENT_MARKER);

        TestBean2 bean = new TestBean2();
        bean.normal = "foo";
        bean.setDef("bar");

        String json = mapper.writeValueAsString(bean);
        assertTrue(json.contains("foo"));
        assertFalse(json.contains("bar"));
        assertFalse(json.contains("def"));

        // Deserialize with field in JSON
        String jsonWithField = "{\"normal\":\"baz\",\"def\":\"shouldBeIgnored\"}";
        TestBean2 bean2 = mapper.readValue(jsonWithField, TestBean2.class);
        assertEquals("baz", bean2.normal);
        // The field should be "world" (default) because it's ignored.
        // But note: the field is transient and has @JsonIgnore, so it should not be set.
        // However, the default value is "world" from the declaration.
        assertEquals("world", bean2.getDef());
    }

    // Test with PROPAGATE_TRANSIENT_MARKER enabled to ensure backward compatibility
    @Test
    public void testTransientFieldWithJsonIgnoreAndPropagateEnabled() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.PROPAGATE_TRANSIENT_MARKER);

        TestBean2 bean = new TestBean2();
        bean.normal = "foo";
        bean.setDef("bar");

        // With PROPAGATE_TRANSIENT_MARKER enabled, transient fields are treated as ignored.
        // But we also have @JsonIgnore, so it should still be ignored.
        String json = mapper.writeValueAsString(bean);
        assertTrue(json.contains("foo"));
        assertFalse(json.contains("bar"));
        assertFalse(json.contains("def"));

        // Deserialize
        String jsonWithField = "{\"normal\":\"baz\",\"def\":\"shouldBeIgnored\"}";
        TestBean2 bean2 = mapper.readValue(jsonWithField, TestBean2.class);
        assertEquals("baz", bean2.normal);
        assertEquals("world", bean2.getDef());
    }
}

