package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.CoercionConfigs;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;

import java.util.Locale;

import static org.junit.Assert.*;

public class CoercionConfigsLocaleEmptyStringTest {

    @Test
    public void testEmptyStringToLocaleWithAcceptEmptyStringAsNullObject() throws Exception {
        // This test reproduces issue #4009: Locale "" should be deserialized as Locale.ROOT
        // even when ACCEPT_EMPTY_STRING_AS_NULL_OBJECT is enabled.
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, true);

        // Before the patch, this would return null because the empty string would be coerced to null.
        // After the patch, it should return Locale.ROOT because Locale is an OtherScalar type
        // and should trigger TryConvert action.
        Locale result = mapper.readValue("\"\"", Locale.class);

        // Assert that the result is Locale.ROOT (not null)
        assertNotNull("Deserialization of empty string to Locale should not return null", result);
        assertEquals("Deserialization of empty string to Locale should yield Locale.ROOT", 
                     Locale.ROOT, result);
    }

    @Test
    public void testFindCoercionForEmptyStringWithOtherScalar() {
        // Direct test of the findCoercion method logic
        DeserializationConfig config = new ObjectMapper().getDeserializationConfig()
                .with(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);

        CoercionConfigs coercionConfigs = new CoercionConfigs();

        // For LogicalType.OtherScalar (which includes Locale), the method should return TryConvert
        // regardless of ACCEPT_EMPTY_STRING_AS_NULL_OBJECT being enabled.
        CoercionAction action = coercionConfigs.findCoercion(
                config,
                LogicalType.OtherScalar,
                Locale.class,
                CoercionInputShape.EmptyString
        );

        // Before the patch, this would return AsNull because the check for OtherScalar
        // came after the check for ACCEPT_EMPTY_STRING_AS_NULL_OBJECT.
        // After the patch, it should return TryConvert.
        assertEquals("For OtherScalar with empty string input, action should be TryConvert",
                     CoercionAction.TryConvert, action);
    }

    @Test
    public void testEmptyStringToLocaleWithoutFeature() throws Exception {
        // Also test that without the feature, empty string still converts to Locale.ROOT
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, false);

        Locale result = mapper.readValue("\"\"", Locale.class);

        // Should still be Locale.ROOT because Locale is an OtherScalar type
        assertNotNull(result);
        assertEquals(Locale.ROOT, result);
    }

    @Test
    public void testEmptyStringToRegularScalarWithFeature() throws Exception {
        // Contrast with a regular scalar type (e.g., Integer) to ensure the feature still works
        // for those types. Integer is not OtherScalar, so it should be coerced to null.
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, true);

        Integer result = mapper.readValue("\"\"", Integer.class);

        // For regular scalar types, empty string should be null when feature is enabled
        assertNull("Empty string to Integer should be null when ACCEPT_EMPTY_STRING_AS_NULL_OBJECT is enabled",
                   result);
    }
}

