import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class StdDeserializerNestedArrayTest {

    // Test class for primitive long deserialization
    public static class LongWrapper {
        @JsonDeserialize(using = LongDeserializer.class)
        private long value;

        public long getValue() {
            return value;
        }

        public void setValue(long value) {
            this.value = value;
        }
    }

    // Custom deserializer that extends StdDeserializer to test _parseLongPrimitive
    public static class LongDeserializer extends StdDeserializer<Long> {
        public LongDeserializer() {
            super(Long.class);
        }

        @Override
        public Long deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            return _parseLongPrimitive(p, ctxt);
        }
    }

    @Test
    public void testNestedArrayWithUnwrapSingleValueArraysForLong() throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Test case 1: Single level array should work (before and after patch)
        String jsonSingle = "{\"value\":[42]}";
        LongWrapper wrapper = mapper.readValue(jsonSingle, LongWrapper.class);
        assertEquals(42L, wrapper.getValue());

        // Test case 2: Deeply nested array should fail with clear error message
        // This is the main test for the patch - before patch it would cause
        // stack overflow or infinite recursion, after patch it should throw exception
        String jsonNested = "{\"value\":[[[42]]]}";

        try {
            mapper.readValue(jsonNested, LongWrapper.class);
            // Before patch: this might succeed (incorrectly) or throw different exception
            // We expect MismatchedInputException after patch
            fail("Expected MismatchedInputException for nested array with UNWRAP_SINGLE_VALUE_ARRAYS");
        } catch (MismatchedInputException e) {
            // After patch: should throw with message about nested arrays
            String message = e.getMessage();
            assertTrue("Error message should mention nested arrays",
                    message.contains("nested Arrays not allowed") ||
                    message.contains("UNWRAP_SINGLE_VALUE_ARRAYS"));
        } catch (Exception e) {
            // Before patch: might throw different exception (like StackOverflowError)
            // or JsonProcessingException. We'll let the test fail to show the issue.
            throw new AssertionError("Unexpected exception type before patch: " + e.getClass().getName(), e);
        }
    }

