    @Test
    public void testDeserializeWrappedValueWithNestedArray() throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Create a simple deserializer that uses _deserializeWrappedValue
        // We'll test with a String deserializer since _deserializeWrappedValue is used there
        String jsonNested = "[[[\"test\"]]]";

        try {
            String result = mapper.readValue(jsonNested, String.class);
            // Before patch: might return "test" (incorrectly)
            // After patch: should throw exception
            fail("Expected MismatchedInputException for nested string array");
        } catch (MismatchedInputException e) {
            // After patch: success
            String message = e.getMessage();
            assertTrue("Error message should mention nested arrays",
                    message.contains("nested Arrays not allowed") ||
                    message.contains("UNWRAP_SINGLE_VALUE_ARRAYS"));
        } catch (Exception e) {
            // Before patch behavior
            throw new AssertionError("Unexpected exception type before patch: " + e.getClass().getName(), e);
        }
    }

    @Test
    public void testNormalSingleArrayStillWorks() throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Single level arrays should still work correctly after patch
        assertEquals(42L, (long) mapper.readValue("[42]", Long.class));
        assertEquals(true, mapper.readValue("[true]", Boolean.class));
        assertEquals(123, (int) mapper.readValue("[123]", Integer.class));
