    // Test bean with field-based any setter
    static class BeanWithFieldAnySetter {
        @JsonAnySetter
        public Map<String, String> other;

        // No initialization - field is null by default
    }

    // Test bean with method-based any setter (should work as before)
    static class BeanWithMethodAnySetter {
        private Map<String, String> other = null;

