        }
    }

    // Test bean with raw Map field
    static class BeanWithRawMap {
        @JsonAnySetter
        public Map other;
    }

    // Test bean with unsupported Map type (abstract)
    static abstract class AbstractMap<K,V> extends HashMap<K,V> {
        // abstract class cannot be instantiated
    }

    static class BeanWithAbstractMap {
        @JsonAnySetter
        public AbstractMap<String, String> other;
    }

    @Test
    public void testFieldAnySetterWithNullMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"extra\":\"value\"}";

