        // After patch: map should be created and populated
        BeanWithFieldAnySetter bean = mapper.readValue(json, BeanWithFieldAnySetter.class);

        assertNotNull("Map should be initialized", bean.other);
        assertEquals(1, bean.other.size());
        assertEquals("value", bean.other.get("extra"));
        // Also check the type: should be LinkedHashMap (default for raw Map) but field is Map<String,String>
        // Actually, the field type is Map<String,String>, but the instantiated map is LinkedHashMap.
        // Since we assign to a Map<String,String> variable, it's fine.
        assertTrue(bean.other instanceof LinkedHashMap);
