        // which could throw NPE if ctxt is null. But in the patch, we added _generator which returns null if ctxt is null.
        // However, the method is called from _createAndSetMap with null ctxt.
        // We can test that creating an exception with null context does not throw NPE.
        JsonMappingException e = JsonMappingException.from((SerializerProvider) null, "Test message");
        assertNotNull(e);
