package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonMappingException;
import org.junit.Test;

import static org.junit.Assert.*;

public class FactoryBasedEnumDeserializerTest {

    @JsonFormat(shape = JsonFormat.Shape.OBJECT)
    public enum DualCreatorEnum {
        A("AType", "A"),
        B("BType", "B");

        private final String type;
        private final String name;

        DualCreatorEnum(String type, String name) {
            this.type = type;
            this.name = name;
        }

        @JsonProperty("type")
        public String getType() {
            return type;
        }

        @JsonProperty("name")
        public String getName() {
            return name;
        }

        // Property-based creator
        @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
        public static DualCreatorEnum fromProperties(@JsonProperty("type") String type,
                                                     @JsonProperty("name") String name) {
            for (DualCreatorEnum e : values()) {
                if (e.type.equals(type) && e.name.equals(name)) {
                    return e;
                }
            }
            throw new IllegalArgumentException("No enum with type=" + type + ", name=" + name);
        }

        // Delegating creator
        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public static DualCreatorEnum fromString(String type) {
            for (DualCreatorEnum e : values()) {
                if (e.type.equals(type)) {
                    return e;
                }
            }
            throw new IllegalArgumentException("No enum with type=" + type);
        }
    }

    @Test
    public void testDualCreatorEnumWithStringInput() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // This should use the delegating creator (fromString) when given a JSON string
        DualCreatorEnum result = mapper.readValue("\"AType\"", DualCreatorEnum.class);

        // Before the patch, this would throw MismatchedInputException because
        // the property-based creator block would incorrectly reject non-object tokens
        // even though a delegating creator exists.
        assertEquals(DualCreatorEnum.A, result);
    }

    @Test
    public void testDualCreatorEnumWithObjectInput() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // This should use the property-based creator when given a JSON object
        String json = "{\"type\":\"AType\",\"name\":\"A\"}";
        DualCreatorEnum result = mapper.readValue(json, DualCreatorEnum.class);

        assertEquals(DualCreatorEnum.A, result);
    }

    @Test
    public void testDualCreatorEnumWithCaseInsensitiveProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.ACCEPT_CASE_INSENSITIVE_PROPERTIES);

        // Test that property-based creator works with case-insensitive property names
        String json = "{\"TYPE\":\"AType\",\"NAME\":\"A\"}";
        DualCreatorEnum result = mapper.readValue(json, DualCreatorEnum.class);

        assertEquals(DualCreatorEnum.A, result);
    }

    @Test
    public void testDualCreatorEnumWithUnwrappedArray() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Test that delegating creator works with unwrapped array
        DualCreatorEnum result = mapper.readValue("[\"AType\"]", DualCreatorEnum.class);

        assertEquals(DualCreatorEnum.A, result);
    }

    @Test(expected = JsonMappingException.class)
    public void testDualCreatorEnumWithInvalidString() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // This should throw because "InvalidType" doesn't match any enum
        mapper.readValue("\"InvalidType\"", DualCreatorEnum.class);
    }

    @Test(expected = JsonMappingException.class)
    public void testDualCreatorEnumWithInvalidObject() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // This should throw because property-based creator requires both properties
        String json = "{\"type\":\"AType\"}";
        mapper.readValue(json, DualCreatorEnum.class);
    }

    // Test enum with only property-based creator (no delegating)
    @JsonFormat(shape = JsonFormat.Shape.OBJECT)
    public enum PropertyOnlyEnum {
        X("XType", "X"),
        Y("YType", "Y");

        private final String type;
        private final String name;

        PropertyOnlyEnum(String type, String name) {
            this.type = type;
            this.name = name;
        }

        @JsonProperty("type")
        public String getType() {
            return type;
        }

        @JsonProperty("name")
        public String getName() {
            return name;
        }

        // Only property-based creator, no delegating creator
        @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
        public static PropertyOnlyEnum fromProperties(@JsonProperty("type") String type,
                                                      @JsonProperty("name") String name) {
            for (PropertyOnlyEnum e : values()) {
                if (e.type.equals(type) && e.name.equals(name)) {
                    return e;
                }
            }
            throw new IllegalArgumentException("No enum with type=" + type + ", name=" + name);
        }
    }

    @Test(expected = JsonMappingException.class)
    public void testPropertyOnlyEnumWithStringInputShouldFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // This should fail because there's no delegating creator to handle string input
        // The patch ensures this throws an appropriate error message
        mapper.readValue("\"XType\"", PropertyOnlyEnum.class);
    }

    @Test
    public void testPropertyOnlyEnumWithObjectInputShouldPass() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"type\":\"XType\",\"name\":\"X\"}";
        PropertyOnlyEnum result = mapper.readValue(json, PropertyOnlyEnum.class);

        assertEquals(PropertyOnlyEnum.X, result);
    }
}

