import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.junit.Test;

import static org.junit.Assert.*;

public class BeanDeserializerBaseExternalTypeHandlerTest {

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Parent {
        public Child child;
    }

    public static class Child {
        public String childType;

        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "childType")
        @JsonSubTypes({
            @JsonSubTypes.Type(value = SubChildA.class, name = "A"),
            @JsonSubTypes.Type(value = SubChildB.class, name = "B")
        })
        public SubChild subChild;
    }

    public static abstract class SubChild {
    }

    public static class SubChildA extends SubChild {
        public String valueA;
    }

    public static class SubChildB extends SubChild {
        public String valueB;
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class GrandParent {
        public Parent parent;
    }

    @Test
    public void testExternalTypeHandlerWithJsonIgnoreProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // This JSON should deserialize correctly with @JsonTypeInfo using EXTERNAL_PROPERTY
        String json = "{\"child\":{\"childType\":\"A\", \"subChild\": {\"valueA\":\"test\"} }}";

        Parent parent = mapper.readValue(json, Parent.class);

        // Verify the structure was deserialized correctly
        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("A", parent.child.childType);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("test", ((SubChildA) parent.child.subChild).valueA);
    }

    @Test
    public void testExternalTypeHandlerPreservedInCopyConstructors() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with different JSON structures to ensure all copy constructors work
        String json1 = "{\"child\":{\"childType\":\"B\", \"subChild\": {\"valueB\":\"testB\"} }}";
        Parent parent1 = mapper.readValue(json1, Parent.class);

        assertNotNull(parent1);
        assertNotNull(parent1.child);
        assertEquals("B", parent1.child.childType);
        assertTrue(parent1.child.subChild instanceof SubChildB);
        assertEquals("testB", ((SubChildB) parent1.child.subChild).valueB);

        // Test with missing external type property - should fail with clear error
        String json2 = "{\"child\":{\"subChild\": {\"valueA\":\"test\"} }}";
        try {
            mapper.readValue(json2, Parent.class);
            fail("Should have thrown MismatchedInputException due to missing external type property");
        } catch (MismatchedInputException e) {
            // Expected - missing external type property
        }
    }

    @Test
    public void testMultipleLevelsOfInheritanceWithExternalType() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"parent\":{\"child\":{\"childType\":\"A\", \"subChild\": {\"valueA\":\"nested\"} }}}";
        GrandParent grandParent = mapper.readValue(json, GrandParent.class);

        assertNotNull(grandParent);
        assertNotNull(grandParent.parent);
        assertNotNull(grandParent.parent.child);
        assertEquals("A", grandParent.parent.child.childType);
        assertTrue(grandParent.parent.child.subChild instanceof SubChildA);
        assertEquals("nested", ((SubChildA) grandParent.parent.child.subChild).valueA);
    }
}

