package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.MissingNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonNodeWithObjectTest {

    @Test
    public void testWithObjectWithJsonPointer() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        // This should work as a JsonPointer expression
        ObjectNode result = root.withObject("/foo/bar");
        assertNotNull(result);
        // The path should be created
        assertTrue(root.has("foo"));
        JsonNode fooNode = root.get("foo");
        assertTrue(fooNode.isObject());
        ObjectNode fooObj = (ObjectNode) fooNode;
        assertTrue(fooObj.has("bar"));
        assertTrue(fooObj.get("bar").isObject());
    }

    @Test
    public void testWithObjectWithPropertyName() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        // This should be treated as a property name (not a JsonPointer)
        ObjectNode result = root.withObject("propertyName");
        assertNotNull(result);
        // The property should be created directly under root
        assertTrue(root.has("propertyName"));
        assertTrue(root.get("propertyName").isObject());
        assertSame(result, root.get("propertyName"));
    }

    @Test
    public void testWithObjectWithEmptyString() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        // Empty string is a valid JsonPointer (points to root)
        ObjectNode result = root.withObject("");
        assertNotNull(result);
        // Should return the root node itself
        assertSame(root, result);
    }

    @Test
    public void testWithObjectWithNestedPropertyName() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        // This looks like a path but doesn't start with '/', so should be treated as property name
        ObjectNode result = root.withObject("foo/bar");
        assertNotNull(result);
        // Should create a single property with name "foo/bar"
        assertTrue(root.has("foo/bar"));
        assertTrue(root.get("foo/bar").isObject());
        assertSame(result, root.get("foo/bar"));
    }

    @Test
    public void testWithObjectWithExistingProperty() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        // First create a property
        ObjectNode initial = root.putObject("existing");
        // Then call withObject on the same property name
        ObjectNode result = root.withObject("existing");
        assertNotNull(result);
        // Should return the existing object, not create a new one
        assertSame(initial, result);
    }

    @Test
    public void testWithObjectWithJsonPointerCreatesMissingNodes() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        // JsonPointer with multiple levels
        ObjectNode result = root.withObject("/a/b/c");
        assertNotNull(result);
        // Verify all intermediate nodes are created
        assertTrue(root.has("a"));
        JsonNode aNode = root.get("a");
        assertTrue(aNode.isObject());
        ObjectNode aObj = (ObjectNode) aNode;
        assertTrue(aObj.has("b"));
        JsonNode bNode = aObj.get("b");
        assertTrue(bNode.isObject());
        ObjectNode bObj = (ObjectNode) bNode;
        assertTrue(bObj.has("c"));
        assertTrue(bObj.get("c").isObject());
    }

    @Test
    public void testWithObjectConsistencyWithWithArray() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        // Test that withObject behaves similarly to withArray for property names
        ObjectNode objResult = root.withObject("prop");
        ArrayNode arrResult = root.withArray("prop2");

        assertTrue(root.has("prop"));
        assertTrue(root.get("prop").isObject());
        assertTrue(root.has("prop2"));
        assertTrue(root.get("prop2").isArray());

        // Test JsonPointer consistency
        ObjectNode objPtrResult = root.withObject("/path/to/obj");
        ArrayNode arrPtrResult = root.withArray("/path/to/arr");

        JsonNode pathNode = root.path("path").path("to");
        assertTrue(pathNode.isObject());
        ObjectNode pathObj = (ObjectNode) pathNode;
        assertTrue(pathObj.has("obj"));
        assertTrue(pathObj.get("obj").isObject());
        assertTrue(pathObj.has("arr"));
        assertTrue(pathObj.get("arr").isArray());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectOnBaseJsonNodeThrows() {
        // Create a JsonNode that isn't an ObjectNode (e.g., a MissingNode)
        JsonNode node = MissingNode.getInstance();
        // This should throw UnsupportedOperationException since base implementation doesn't support it
        node.withObject("anything");
    }
}

