package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import org.junit.Test;
import static org.junit.Assert.*;

public class BeanUtilTest {

    @Test
    public void testCheckUnsupportedTypeForJava8Optional() {
        // Test that Java 8 optional types are detected as unsupported
        TypeFactory tf = TypeFactory.defaultInstance();

        // Test OptionalInt
        JavaType optionalIntType = tf.constructType(java.util.OptionalInt.class);
        String result = BeanUtil.checkUnsupportedType(optionalIntType);
        assertNotNull("OptionalInt should be detected as unsupported", result);
        assertTrue("Error message should contain 'Java 8 optional'", result.contains("Java 8 optional"));
        assertTrue("Error message should contain 'jackson-datatype-jdk8'", result.contains("jackson-datatype-jdk8"));

        // Test OptionalLong
        JavaType optionalLongType = tf.constructType(java.util.OptionalLong.class);
        result = BeanUtil.checkUnsupportedType(optionalLongType);
        assertNotNull("OptionalLong should be detected as unsupported", result);
        assertTrue("Error message should contain 'Java 8 optional'", result.contains("Java 8 optional"));
        assertTrue("Error message should contain 'jackson-datatype-jdk8'", result.contains("jackson-datatype-jdk8"));

        // Test OptionalDouble
        JavaType optionalDoubleType = tf.constructType(java.util.OptionalDouble.class);
        result = BeanUtil.checkUnsupportedType(optionalDoubleType);
        assertNotNull("OptionalDouble should be detected as unsupported", result);
        assertTrue("Error message should contain 'Java 8 optional'", result.contains("Java 8 optional"));
        assertTrue("Error message should contain 'jackson-datatype-jdk8'", result.contains("jackson-datatype-jdk8"));

        // Test generic Optional
        JavaType optionalType = tf.constructType(java.util.Optional.class);
        result = BeanUtil.checkUnsupportedType(optionalType);
        assertNotNull("Optional should be detected as unsupported", result);
        assertTrue("Error message should contain 'Java 8 optional'", result.contains("Java 8 optional"));
        assertTrue("Error message should contain 'jackson-datatype-jdk8'", result.contains("jackson-datatype-jdk8"));

        // Test that non-optional types return null
        JavaType stringType = tf.constructType(String.class);
        result = BeanUtil.checkUnsupportedType(stringType);
        assertNull("String should not be detected as unsupported", result);

        JavaType integerType = tf.constructType(Integer.class);
        result = BeanUtil.checkUnsupportedType(integerType);
        assertNull("Integer should not be detected as unsupported", result);
    }

    @Test
    public void testIsJava8OptionalClass() {
        // Test the helper method directly
        assertTrue("OptionalInt should be Java 8 optional", 
            BeanUtil.isJava8OptionalClass(java.util.OptionalInt.class));
        assertTrue("OptionalLong should be Java 8 optional", 
            BeanUtil.isJava8OptionalClass(java.util.OptionalLong.class));
        assertTrue("OptionalDouble should be Java 8 optional", 
            BeanUtil.isJava8OptionalClass(java.util.OptionalDouble.class));
        assertTrue("Optional should be Java 8 optional", 
            BeanUtil.isJava8OptionalClass(java.util.Optional.class));

        // Test with non-optional classes
        assertFalse("String should not be Java 8 optional", 
            BeanUtil.isJava8OptionalClass(String.class));
        assertFalse("Integer should not be Java 8 optional", 
            BeanUtil.isJava8OptionalClass(Integer.class));
        assertFalse("List should not be Java 8 optional", 
            BeanUtil.isJava8OptionalClass(java.util.List.class));
    }

    @Test
    public void testIsJava8OptionalClassString() {
        // Test the private method via reflection to ensure it correctly identifies optional classes
        // This test uses reflection to access the private method
        try {
            java.lang.reflect.Method method = BeanUtil.class.getDeclaredMethod("isJava8OptionalClass", String.class);
            method.setAccessible(true);

            assertTrue("java.util.OptionalInt should match", 
                (Boolean) method.invoke(null, "java.util.OptionalInt"));
            assertTrue("java.util.OptionalLong should match", 
                (Boolean) method.invoke(null, "java.util.OptionalLong"));
            assertTrue("java.util.OptionalDouble should match", 
                (Boolean) method.invoke(null, "java.util.OptionalDouble"));
            assertTrue("java.util.Optional should match", 
                (Boolean) method.invoke(null, "java.util.Optional"));
            assertTrue("java.util.Optional.of should match", 
                (Boolean) method.invoke(null, "java.util.Optional.of"));

            assertFalse("java.util.ArrayList should not match", 
                (Boolean) method.invoke(null, "java.util.ArrayList"));
            assertFalse("java.lang.String should not match", 
                (Boolean) method.invoke(null, "java.lang.String"));
            assertFalse("java.time.LocalDate should not match", 
                (Boolean) method.invoke(null, "java.time.LocalDate"));
        } catch (Exception e) {
            fail("Failed to test private method: " + e.getMessage());
        }
    }
}

