package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.type.TypeParser;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeParserGuardrailTest {

    @Test
    public void testParseExceedsMaxLength() {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Build a string longer than MAX_TYPE_LENGTH (64,000)
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.List<");
        // Fill with enough characters to exceed limit
        while (sb.length() <= 64000) {
            sb.append("java.lang.String,");
        }
        sb.append("java.lang.String>");
        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException for too long type string");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertTrue("Error message should mention 'too long'", msg.contains("too long"));
            assertTrue("Error message should contain length", msg.contains("64000"));
            // Verify truncation in message (input longer than 1000 chars gets truncated)
            assertTrue("Error message should contain truncated indicator", 
                       msg.contains("...") || msg.contains("truncated"));
        }
    }

    @Test
    public void testParseExceedsMaxNesting() {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Build a deeply nested type that exceeds MAX_TYPE_NESTING (1000)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1001; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < 1001; i++) {
            sb.append(">");
        }
        String deeplyNested = sb.toString();

        try {
            parser.parse(deeplyNested);
            fail("Expected IllegalArgumentException for too deeply nested type");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertTrue("Error message should mention 'too deeply nested'", 
                       msg.contains("too deeply nested"));
            assertTrue("Error message should mention maximum nesting level", 
                       msg.contains("1000"));
        }
    }

    @Test
    public void testParseWithinLimits() {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Test a valid type within limits
        JavaType type = parser.parse("java.util.Map<java.lang.String, java.util.List<java.lang.Integer>>");
        assertNotNull(type);
        assertEquals("java.util.Map", type.getRawClass().getName());

        // Test with moderate nesting (well below 1000)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 100; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < 100; i++) {
            sb.append(">");
        }
        JavaType nestedType = parser.parse(sb.toString());
        assertNotNull(nestedType);
        assertEquals("java.util.List", nestedType.getRawClass().getName());
    }

    @Test
    public void testQuoteTruncated() throws Exception {
        // Use reflection to test private method _quoteTruncated
        java.lang.reflect.Method method = TypeParser.class.getDeclaredMethod("_quoteTruncated", String.class);
        method.setAccessible(true);

        // Short string should be quoted as-is
        String shortStr = "java.util.List";
        String result = (String) method.invoke(null, shortStr);
        assertEquals("'java.util.List'", result);

        // Long string should be truncated
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1500; i++) {
            sb.append("a");
        }
        String longStr = sb.toString();
        result = (String) method.invoke(null, longStr);
        assertTrue("Should contain '...'", result.contains("..."));
        assertTrue("Should contain 'truncated'", result.contains("truncated"));
        assertTrue("Should start with quote", result.startsWith("'"));
    }

    @Test
    public void testProblemMethodUsesQuoteTruncated() {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Create a tokenizer with long input to trigger _problem
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.List<");
        for (int i = 0; i < 2000; i++) {
            sb.append("a");
        }
        sb.append(">");
        String longInput = sb.toString();

        // Simulate parsing to get to a state where _problem might be called
        try {
            // This will fail because the class "a...a" doesn't exist
            parser.parse(longInput);
            fail("Expected exception");
        } catch (IllegalArgumentException e) {
            // Verify the error message uses truncated quotes
            String msg = e.getMessage();
            assertTrue("Error message should contain truncated input", 
                       msg.contains("...") || msg.contains("truncated"));
        }
    }
}

