package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonMerge;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectReader;
import com.fasterxml.jackson.databind.deser.impl.BeanPropertyMap;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class SettableBeanPropertyPolymorphicMergeTest {

    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.PROPERTY, property = "type")
    @JsonSubTypes({
        @JsonSubTypes.Type(value = ConcreteThingyA.class, name = "A"),
        @JsonSubTypes.Type(value = ConcreteThingyB.class, name = "B")
    })
    public static abstract class BaseThingy {
        public String baseField;
    }

    public static class ConcreteThingyA extends BaseThingy {
        public String aField;
        public int aNumber;
    }

    public static class ConcreteThingyB extends BaseThingy {
        public String bField;
    }

    public static class MyRequest {
        @JsonMerge
        private BaseThingy thingy;

        public BaseThingy getThingy() {
            return thingy;
        }

        public void setThingy(BaseThingy thingy) {
            this.thingy = thingy;
        }
    }

    @Test
    public void testPolymorphicPropertyMergeSameType() throws Exception {
        // Create ObjectMapper with FAIL_ON_UNKNOWN_PROPERTIES disabled to allow merging
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        // Initial object with ConcreteThingyA
        ConcreteThingyA existing = new ConcreteThingyA();
        existing.baseField = "originalBase";
        existing.aField = "originalA";
        existing.aNumber = 42;

        MyRequest request = new MyRequest();
        request.setThingy(existing);

        // JSON to merge - only updates aField, leaves other fields unchanged
        String json = "{\"thingy\": {\"type\": \"A\", \"aField\": \"updatedA\"}}";

        // Merge JSON into existing object
        ObjectReader reader = mapper.readerForUpdating(request);
        MyRequest merged = reader.readValue(json);

        // Verify the merged object
        assertNotNull(merged);
        assertNotNull(merged.getThingy());
        assertTrue(merged.getThingy() instanceof ConcreteThingyA);

        ConcreteThingyA mergedThingy = (ConcreteThingyA) merged.getThingy();

        // Before patch: This would fail with "Cannot merge polymorphic property" exception
        // After patch: Should merge successfully
        assertEquals("originalBase", mergedThingy.baseField); // unchanged
        assertEquals("updatedA", mergedThingy.aField); // updated
        assertEquals(42, mergedThingy.aNumber); // unchanged
    }

    @Test
    public void testPolymorphicPropertyMergeWithNullToken() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        ConcreteThingyA existing = new ConcreteThingyA();
        existing.baseField = "originalBase";
        existing.aField = "originalA";

        MyRequest request = new MyRequest();
        request.setThingy(existing);

        // JSON with null value for polymorphic property
        String json = "{\"thingy\": null}";

        ObjectReader reader = mapper.readerForUpdating(request);
        MyRequest merged = reader.readValue(json);

        // With null token, should return null provider's null value
        assertNull(merged.getThingy());
    }

    @Test
    public void testPolymorphicPropertyMergeDifferentTypeShouldNotMerge() throws Exception {
        // This test demonstrates that merging different subtypes doesn't work
        // (as mentioned in the patch comments)
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        // Start with ConcreteThingyA
        ConcreteThingyA existing = new ConcreteThingyA();
        existing.baseField = "originalBase";
        existing.aField = "originalA";

        MyRequest request = new MyRequest();
        request.setThingy(existing);

        // Try to merge with JSON specifying ConcreteThingyB
        String json = "{\"thingy\": {\"type\": \"B\", \"bField\": \"newB\"}}";

        ObjectReader reader = mapper.readerForUpdating(request);
        MyRequest merged = reader.readValue(json);

        // The behavior here is undefined per patch comments
        // But at least it shouldn't throw "Cannot merge polymorphic property" exception
        assertNotNull(merged.getThingy());
        // It might create a new ConcreteThingyB instance or keep the old one
        // The important thing is no exception is thrown
    }

    @Test
    public void testDirectDeserializeWithMethod() throws Exception {
        // Test the specific method directly
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        // Create a property with polymorphic type info
        // We need to create a SettableBeanProperty with _valueTypeDeserializer != null
        // This is complex to set up directly, so we'll test through the object mapper

        ConcreteThingyA existing = new ConcreteThingyA();
        existing.baseField = "original";
        existing.aField = "originalA";
        existing.aNumber = 100;

        String json = "{\"type\": \"A\", \"aField\": \"newA\"}";
        JsonParser parser = mapper.createParser(json);

        // Skip to start object
        parser.nextToken();

        // Create a new instance to merge into
        ConcreteThingyA toUpdate = new ConcreteThingyA();
        toUpdate.baseField = "original";
        toUpdate.aField = "originalA";
        toUpdate.aNumber = 100;

        // This would trigger the code path in deserializeWith
        // We need to test through ObjectReader since setting up SettableBeanProperty directly is complex
        MyRequest container = new MyRequest();
        container.setThingy(toUpdate);

        String fullJson = "{\"thingy\": " + json + "}";
        MyRequest result = mapper.readerForUpdating(container).readValue(fullJson);

        ConcreteThingyA merged = (ConcreteThingyA) result.getThingy();

        // Before patch: Would throw exception
        // After patch: Should merge
        assertEquals("original", merged.baseField);
        assertEquals("newA", merged.aField);
        assertEquals(100, merged.aNumber);
    }

    @Test
    public void testPolymorphicMergeWithEmptyUpdate() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        // Start with empty request
        MyRequest request = new MyRequest();

        // JSON with full ConcreteThingyA
        String json = "{\"thingy\": {\"type\": \"A\", \"baseField\": \"base\", \"aField\": \"a\", \"aNumber\": 123}}";

        ObjectReader reader = mapper.readerForUpdating(request);
        MyRequest merged = reader.readValue(json);

        assertNotNull(merged.getThingy());
        assertTrue(merged.getThingy() instanceof ConcreteThingyA);

        ConcreteThingyA thingy = (ConcreteThingyA) merged.getThingy();
        assertEquals("base", thingy.baseField);
        assertEquals("a", thingy.aField);
        assertEquals(123, thingy.aNumber);
    }
}

