package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotationMap;
import com.fasterxml.jackson.databind.introspect.NopAnnotationIntrospector;

import java.lang.annotation.Annotation;

import org.junit.Test;
import static org.junit.Assert.*;

public class AnnotationIntrospectorPairMergeTest {

    // Mock introspector that returns a PropertyName with empty simple name and namespace
    static class PrimaryIntrospector extends NopAnnotationIntrospector {
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            // Simulate @JacksonXmlProperty with defaults: empty local name and namespace
            return new PropertyName("", "");
        }
    }

    // Mock introspector that returns a PropertyName with explicit simple name and namespace
    static class SecondaryIntrospector extends NopAnnotationIntrospector {
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            // Simulate @JsonProperty with namespace and value
            return new PropertyName("prop", "uri:ns1");
        }
    }

    @Test
    public void testFindNameForSerializationMerge() {
        AnnotationIntrospector primary = new PrimaryIntrospector();
        AnnotationIntrospector secondary = new SecondaryIntrospector();
        AnnotationIntrospector pair = AnnotationIntrospectorPair.create(primary, secondary);

        // Create a simple Annotated implementation using AnnotatedClass's constructor
        // that only takes a Class parameter (available in the codebase)
        Annotated dummy = new AnnotatedClass(Object.class);

        PropertyName result = pair.findNameForSerialization(dummy);

        // After the patch, merge should use secondary's explicit values when primary has empty strings
        assertNotNull(result);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
    }

    // Additionally, test the merge method directly to ensure it works as expected.
    @Test
    public void testPropertyNameMerge() {
        PropertyName empty = new PropertyName("", "");
        PropertyName explicit = new PropertyName("prop", "uri:ns1");

        // Merge with empty first (higher precedence) and explicit second.
        PropertyName merged = PropertyName.merge(empty, explicit);
        assertNotNull(merged);
        assertEquals("prop", merged.getSimpleName());
        assertEquals("uri:ns1", merged.getNamespace());

        // Merge with explicit first and empty second.
        merged = PropertyName.merge(explicit, empty);
        // Since explicit has non-empty values, they should be used.
        assertEquals("prop", merged.getSimpleName());
        assertEquals("uri:ns1", merged.getNamespace());

        // Merge with null first and explicit second.
        merged = PropertyName.merge(null, explicit);
        assertSame(explicit, merged);

        // Merge with explicit first and null second.
        merged = PropertyName.merge(explicit, null);
        assertSame(explicit, merged);

        // Merge with both null.
        merged = PropertyName.merge(null, null);
        assertNull(merged);
    }
}

