package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.exc.InvalidNullException;
import org.junit.Test;

import java.util.Map;

import static org.junit.Assert.*;

public class BeanDeserializerBaseDelegatingCreatorTest {

    // Test class that uses delegating creator with @JsonSetter(contentNulls = Nulls.FAIL)
    public static class DelegatingWrapper {
        private final Map<String, String> map;

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public DelegatingWrapper(@JsonSetter(contentNulls = Nulls.FAIL) Map<String, String> map) {
            this.map = map;
        }

        public Map<String, String> getMap() {
            return map;
        }
    }

    @Test
    public void testDelegatingCreatorWithContentNullsFail() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // This should throw InvalidNullException because contentNulls = FAIL
        // and we have null value in map content
        try {
            mapper.readValue("{\"foo\":null}", DelegatingWrapper.class);
            fail("Expected InvalidNullException to be thrown");
        } catch (InvalidNullException e) {
            // Expected - test passes with patch
            assertTrue(e.getMessage().contains("foo"));
        } catch (Exception e) {
            fail("Expected InvalidNullException but got: " + e.getClass().getName());
        }
    }

    @Test
    public void testDelegatingCreatorWithNonNullContent() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // This should work fine - no null values in map
        DelegatingWrapper wrapper = mapper.readValue("{\"foo\":\"bar\"}", DelegatingWrapper.class);
        assertNotNull(wrapper);
        assertNotNull(wrapper.getMap());
        assertEquals("bar", wrapper.getMap().get("foo"));
    }

    @Test
    public void testDelegatingCreatorWithMultipleNulls() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // Multiple null values should all trigger the exception
        try {
            mapper.readValue("{\"foo\":null,\"bar\":null}", DelegatingWrapper.class);
            fail("Expected InvalidNullException to be thrown");
        } catch (InvalidNullException e) {
            // Expected - test passes with patch
            assertTrue(e.getMessage().contains("foo") || e.getMessage().contains("bar"));
        }
    }

    // Additional test class with nulls = FAIL (for value null handling)
    public static class DelegatingWrapperValueNulls {
        private final Map<String, String> map;

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public DelegatingWrapperValueNulls(@JsonSetter(nulls = Nulls.FAIL) Map<String, String> map) {
            this.map = map;
        }

        public Map<String, String> getMap() {
            return map;
        }
    }

    @Test
    public void testDelegatingCreatorWithValueNullsFail() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // nulls = FAIL should not trigger for map content nulls
        // (nulls refers to the map itself being null, not its contents)
        // So this should work
        DelegatingWrapperValueNulls wrapper = mapper.readValue("{\"foo\":null}", DelegatingWrapperValueNulls.class);
        assertNotNull(wrapper);
        assertNotNull(wrapper.getMap());
        assertNull(wrapper.getMap().get("foo"));
    }

