    public static class DelegatingWrapperBothNulls {
        private final Map<String, String> map;

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public DelegatingWrapperBothNulls(
                @JsonSetter(nulls = Nulls.FAIL, contentNulls = Nulls.FAIL) 
                Map<String, String> map) {
            this.map = map;
        }

        public Map<String, String> getMap() {
            return map;
        }
    }

    @Test
    public void testDelegatingCreatorWithBothNullsFail() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // Should fail on content nulls
        try {
            mapper.readValue("{\"foo\":null}", DelegatingWrapperBothNulls.class);
            fail("Expected InvalidNullException to be thrown");
        } catch (InvalidNullException e) {
            // Expected - test passes with patch
            assertTrue(e.getMessage().contains("foo"));
        }
    }

    // Test to ensure non-delegating creators still work
    public static class PropertiesCreatorWrapper {
        private final Map<String, String> map;

        @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
        public PropertiesCreatorWrapper(@com.fasterxml.jackson.annotation.JsonProperty("map") @JsonSetter(contentNulls = Nulls.FAIL) Map<String, String> map) {
            this.map = map;
        }

        public Map<String, String> getMap() {
            return map;
        }
    }

    @Test
    public void testPropertiesCreatorWithContentNullsFail() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // PROPERTIES mode should already work (regression test)
        try {
            mapper.readValue("{\"map\":{\"foo\":null}}", PropertiesCreatorWrapper.class);
            fail("Expected InvalidNullException to be thrown");
        } catch (InvalidNullException e) {
            // Expected
            assertTrue(e.getMessage().contains("foo"));
        }
    }
}

