package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;

import static org.junit.Assert.*;

public class CoercionConfigsTest {

    @Test
    public void testAllowCoercionOfScalarsDisabledWithIntegerToFloat() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        ObjectMapper mapper = new ObjectMapper();
        DeserializationConfig config = mapper.getDeserializationConfig()
                .with(MapperFeature.ALLOW_COERCION_OF_SCALARS, false);

        // Test integer-to-float coercion: should NOT return Fail when feature is disabled
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,        // target type
                Float.class,              // target class
                CoercionInputShape.Integer // input shape
        );

        // Before patch: returns CoercionAction.Fail
        // After patch: should NOT return CoercionAction.Fail (should be something else)
        assertNotEquals("Integer-to-float coercion should not fail when ALLOW_COERCION_OF_SCALARS is disabled",
                CoercionAction.Fail, action);

        // Verify that the action is one of the valid non-fail actions
        assertTrue("Action should be a valid coercion action",
                action == CoercionAction.TryConvert || 
                action == CoercionAction.AsNull || 
                action == CoercionAction.AsEmpty);
    }

    @Test
    public void testAllowCoercionOfScalarsDisabledWithNonFloatScalar() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        ObjectMapper mapper = new ObjectMapper();
        DeserializationConfig config = mapper.getDeserializationConfig()
                .with(MapperFeature.ALLOW_COERCION_OF_SCALARS, false);

        // Test integer-to-integer coercion: should return Fail when feature is disabled
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Integer,      // target type (non-float scalar)
                Integer.class,            // target class
                CoercionInputShape.Integer // input shape
        );

        // Both before and after patch: should return CoercionAction.Fail
        assertEquals("Non-float scalar coercion should fail when ALLOW_COERCION_OF_SCALARS is disabled",
                CoercionAction.Fail, action);
    }

    @Test
    public void testAllowCoercionOfScalarsDisabledWithStringToFloat() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        ObjectMapper mapper = new ObjectMapper();
        DeserializationConfig config = mapper.getDeserializationConfig()
                .with(MapperFeature.ALLOW_COERCION_OF_SCALARS, false);

        // Test string-to-float coercion: should return Fail when feature is disabled
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,        // target type
                Float.class,              // target class
                CoercionInputShape.String // input shape (not Integer)
        );

        // Both before and after patch: should return CoercionAction.Fail
        assertEquals("String-to-float coercion should fail when ALLOW_COERCION_OF_SCALARS is disabled",
                CoercionAction.Fail, action);
    }

    @Test
    public void testAllowCoercionOfScalarsEnabledWithIntegerToFloat() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS enabled (default)
        ObjectMapper mapper = new ObjectMapper();
        DeserializationConfig config = mapper.getDeserializationConfig()
                .with(MapperFeature.ALLOW_COERCION_OF_SCALARS, true);

        // Test integer-to-float coercion: should NOT return Fail when feature is enabled
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,        // target type
                Float.class,              // target class
                CoercionInputShape.Integer // input shape
        );

        // Both before and after patch: should NOT return CoercionAction.Fail
        assertNotEquals("Integer-to-float coercion should not fail when ALLOW_COERCION_OF_SCALARS is enabled",
                CoercionAction.Fail, action);
    }

    @Test
    public void testIntegerToFloatCoercionWithPerTypeConfig() {
        // Create a CoercionConfigs instance
        CoercionConfigs configs = new CoercionConfigs();

        // Set up a per-type coercion for Float to TryConvert for Integer input
        MutableCoercionConfig floatCoercion = configs.findOrCreateCoercion(LogicalType.Float);
        floatCoercion.setCoercion(CoercionInputShape.Integer, CoercionAction.TryConvert);

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        ObjectMapper mapper = new ObjectMapper();
        DeserializationConfig config = mapper.getDeserializationConfig()
                .with(MapperFeature.ALLOW_COERCION_OF_SCALARS, false);

        // Test integer-to-float coercion: should return TryConvert (from per-type config)
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,        // target type
                Float.class,              // target class
                CoercionInputShape.Integer // input shape
        );

        // Before patch: returns CoercionAction.Fail (ignores per-type config)
        // After patch: should return CoercionAction.TryConvert (respects per-type config)
        assertEquals("Integer-to-float coercion should respect per-type configuration",
                CoercionAction.TryConvert, action);
    }

    @Test
    public void testIntegerToDoubleCoercion() {
        // Create a CoercionConfigs instance with default settings
        CoercionConfigs configs = new CoercionConfigs();

        // Create a DeserializationConfig with ALLOW_COERCION_OF_SCALARS disabled
        ObjectMapper mapper = new ObjectMapper();
        DeserializationConfig config = mapper.getDeserializationConfig()
                .with(MapperFeature.ALLOW_COERCION_OF_SCALARS, false);

        // Test integer-to-double coercion: Double is also LogicalType.Float
        CoercionAction action = configs.findCoercion(
                config,
                LogicalType.Float,        // target type (Double is also Float logical type)
                Double.class,             // target class
                CoercionInputShape.Integer // input shape
        );

        // Before patch: returns CoercionAction.Fail
        // After patch: should NOT return CoercionAction.Fail
        assertNotEquals("Integer-to-double coercion should not fail when ALLOW_COERCION_OF_SCALARS is disabled",
                CoercionAction.Fail, action);
    }
}

