package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.type.LogicalType;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import java.io.IOException;
import java.math.BigDecimal;

import org.junit.Test;
import static org.junit.Assert.*;

public class DoubleDeserializerTest {

    private ObjectMapper createMapperWithCoercion(CoercionAction action) {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, action);
        return mapper;
    }

    @Test
    public void testIntToDoubleCoercionFail() throws IOException {
        ObjectMapper mapper = createMapperWithCoercion(CoercionAction.Fail);
        try {
            mapper.readValue("42", Double.class);
            fail("Should have thrown MismatchedInputException");
        } catch (MismatchedInputException e) {
            // Expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }
    }

    @Test
    public void testIntToDoubleCoercionAsNull() throws IOException {
        ObjectMapper mapper = createMapperWithCoercion(CoercionAction.AsNull);
        Double result = mapper.readValue("42", Double.class);
        assertNull(result);
