package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.Version;
import org.junit.Test;
import static org.junit.Assert.*;

public class AnnotationIntrospectorPairMergeTest {

    // Helper class to simulate an AnnotationIntrospector that returns a specific PropertyName
    static class SimpleIntrospector extends com.fasterxml.jackson.databind.AnnotationIntrospector {
        private static final long serialVersionUID = 1L;
        private final PropertyName rootName;
        private final PropertyName wrapperName;
        private final PropertyName serializationName;
        private final PropertyName deserializationName;
        private final PropertyName renameByField;

        SimpleIntrospector(PropertyName rootName, PropertyName wrapperName,
                           PropertyName serializationName, PropertyName deserializationName,
                           PropertyName renameByField) {
            this.rootName = rootName;
            this.wrapperName = wrapperName;
            this.serializationName = serializationName;
            this.deserializationName = deserializationName;
            this.renameByField = renameByField;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return rootName;
        }

        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return wrapperName;
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return serializationName;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return deserializationName;
        }

        @Override
        public PropertyName findRenameByField(MapperConfig<?> config,
                                              AnnotatedField f, PropertyName implName) {
            return renameByField;
        }

        @Override
        public Version version() {
            return Version.unknownVersion();
        }
    }

    @Test
    public void testFindRootNameMerge() {
        // Test merging: primary has non-empty, secondary has empty
        PropertyName primary = new PropertyName("root1", "ns1");
        PropertyName secondary = new PropertyName("", "");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        PropertyName result = pair.findRootName(null);
        assertEquals(primary, result);
        assertEquals("root1", result.getSimpleName());
        assertEquals("ns1", result.getNamespace());

        // Test merging: primary empty, secondary non-empty
        primary = new PropertyName("", "");
        secondary = new PropertyName("root2", "ns2");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        result = pair.findRootName(null);
        assertEquals(secondary, result);
        assertEquals("root2", result.getSimpleName());
        assertEquals("ns2", result.getNamespace());

        // Test merging: primary null, secondary non-empty
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        result = pair.findRootName(null);
        assertEquals(secondary, result);

        // Test merging: primary non-empty, secondary null
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(null, null, null, null, null)
        );
        result = pair.findRootName(null);
        assertEquals(primary, result);

        // Test merging: both null -> null
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, null, null),
                new SimpleIntrospector(null, null, null, null, null)
        );
        assertNull(pair.findRootName(null));

        // Test merging: primary empty simple name but non-empty namespace, secondary non-empty both
        primary = new PropertyName("", "nsPrimary");
        secondary = new PropertyName("simple2", "nsSecondary");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        result = pair.findRootName(null);
        // primary empty simple name -> use secondary's simple name
        assertEquals("simple2", result.getSimpleName());
        // primary non-empty namespace -> use primary's namespace
        assertEquals("nsPrimary", result.getNamespace());
    }

    @Test
    public void testFindWrapperNameMerge() {
        PropertyName primary = new PropertyName("wrap1", "ns1");
        PropertyName secondary = new PropertyName("", "");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, primary, null, null, null),
                new SimpleIntrospector(null, secondary, null, null, null)
        );
        PropertyName result = pair.findWrapperName(null);
        assertEquals(primary, result);

        // Test USE_DEFAULT handling: primary USE_DEFAULT, secondary non-empty
        primary = PropertyName.USE_DEFAULT;
        secondary = new PropertyName("wrap2", "ns2");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, primary, null, null, null),
                new SimpleIntrospector(null, secondary, null, null, null)
        );
        result = pair.findWrapperName(null);
        // merge should pick secondary because primary is USE_DEFAULT (which is empty)
        assertEquals(secondary, result);
    }

    @Test
    public void testFindNameForSerializationMerge() {
        PropertyName primary = new PropertyName("serial1", "ns1");
        PropertyName secondary = new PropertyName("", "");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, primary, null, null),
                new SimpleIntrospector(null, null, secondary, null, null)
        );
        PropertyName result = pair.findNameForSerialization(null);
        assertEquals(primary, result);

        // Test USE_DEFAULT handling
        primary = PropertyName.USE_DEFAULT;
        secondary = new PropertyName("serial2", "ns2");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, primary, null, null),
                new SimpleIntrospector(null, null, secondary, null, null)
        );
        result = pair.findNameForSerialization(null);
        assertEquals(secondary, result);
    }

    @Test
    public void testFindNameForDeserializationMerge() {
        PropertyName primary = new PropertyName("deserial1", "ns1");
        PropertyName secondary = new PropertyName("", "");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, primary, null),
                new SimpleIntrospector(null, null, null, secondary, null)
        );
        PropertyName result = pair.findNameForDeserialization(null);
        assertEquals(primary, result);

        // Test USE_DEFAULT handling
        primary = PropertyName.USE_DEFAULT;
        secondary = new PropertyName("deserial2", "ns2");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, primary, null),
                new SimpleIntrospector(null, null, null, secondary, null)
        );
        result = pair.findNameForDeserialization(null);
        assertEquals(secondary, result);
    }

    @Test
    public void testFindRenameByFieldMerge() {
        // Note: order is swapped: secondary first, then primary
        PropertyName secondary = new PropertyName("rename1", "ns1");
        PropertyName primary = new PropertyName("", "");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, null, primary),
                new SimpleIntrospector(null, null, null, null, secondary)
        );
        PropertyName result = pair.findRenameByField(null, null, null);
        // secondary has higher precedence in this method
        assertEquals(secondary, result);

        // Test with primary non-empty, secondary empty
        secondary = new PropertyName("", "");
        primary = new PropertyName("rename2", "ns2");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, null, primary),
                new SimpleIntrospector(null, null, null, null, secondary)
        );
        result = pair.findRenameByField(null, null, null);
        // secondary empty, so primary should be used
        assertEquals(primary, result);
    }

    // Integration test with actual annotations (requires xml module)
    @Test
    public void testMergeWithActualAnnotations() throws Exception {
        // Simulate the scenario: @JacksonXmlProperty (empty defaults) and @JsonProperty with explicit values
        // We'll create a simple class with both annotations and use XmlMapper (which uses JacksonXmlAnnotationIntrospector)
        // and JacksonAnnotationIntrospector.
        // Since we cannot easily instantiate the introspectors directly, we rely on the mapper's behavior.
        // However, we can test PropertyName.merge directly.
        PropertyName fromXml = new PropertyName("", ""); // JacksonXmlProperty defaults
        PropertyName fromJson = new PropertyName("prop", "uri:ns1");
        PropertyName merged = PropertyName.merge(fromXml, fromJson);
        assertEquals("prop", merged.getSimpleName());
        assertEquals("uri:ns1", merged.getNamespace());

        // Reverse order: Json first, Xml second (Json higher precedence)
        merged = PropertyName.merge(fromJson, fromXml);
        assertEquals("prop", merged.getSimpleName());
        assertEquals("uri:ns1", merged.getNamespace());
    }

    @Test
    public void testPropertyNameMergeMethod() {
        // Test merge with null inputs
        assertNull(PropertyName.merge(null, null));
        PropertyName pn = new PropertyName("test", "ns");
        assertEquals(pn, PropertyName.merge(pn, null));
        assertEquals(pn, PropertyName.merge(null, pn));

        // Test merge with empty strings
        PropertyName empty1 = new PropertyName("", "");
        PropertyName nonEmpty = new PropertyName("simple", "namespace");
        PropertyName merged = PropertyName.merge(empty1, nonEmpty);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("namespace", merged.getNamespace());

        // Test merge with non-empty first, empty second
        merged = PropertyName.merge(nonEmpty, empty1);
        assertEquals(nonEmpty, merged);

        // Test merge with both non-empty: first takes precedence
        PropertyName other = new PropertyName("other", "otherNs");
        merged = PropertyName.merge(nonEmpty, other);
        assertEquals(nonEmpty, merged);

        // Test merge with same values returns same instance
        PropertyName same = new PropertyName("simple", "namespace");
        merged = PropertyName.merge(nonEmpty, same);
        assertSame(nonEmpty, merged); // should return first argument because identical

        // Test merge with first empty simple name but non-empty namespace
        PropertyName partial = new PropertyName("", "ns1");
        PropertyName full = new PropertyName("simple2", "ns2");
        merged = PropertyName.merge(partial, full);
        assertEquals("simple2", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
    }
}

