        PropertyName secondary = new PropertyName("", "");
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        PropertyName result = pair.findRootName(null);
        assertEquals(primary, result);
        assertEquals("root1", result.getSimpleName());
        assertEquals("ns1", result.getNamespace());

        // Test merging: primary empty, secondary non-empty
        primary = new PropertyName("", "");
        secondary = new PropertyName("root2", "ns2");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        result = pair.findRootName(null);
        assertEquals(secondary, result);
        assertEquals("root2", result.getSimpleName());
        assertEquals("ns2", result.getNamespace());

        // Test merging: primary null, secondary non-empty
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        result = pair.findRootName(null);
        assertEquals(secondary, result);

        // Test merging: primary non-empty, secondary null
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(null, null, null, null, null)
        );
        result = pair.findRootName(null);
        assertEquals(primary, result);

        // Test merging: both null -> null
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(null, null, null, null, null),
                new SimpleIntrospector(null, null, null, null, null)
        );
        assertNull(pair.findRootName(null));

        // Test merging: primary empty simple name but non-empty namespace, secondary non-empty both
        primary = new PropertyName("", "nsPrimary");
        secondary = new PropertyName("simple2", "nsSecondary");
        pair = new AnnotationIntrospectorPair(
                new SimpleIntrospector(primary, null, null, null, null),
                new SimpleIntrospector(secondary, null, null, null, null)
        );
        result = pair.findRootName(null);
        // primary empty simple name -> use secondary's simple name
        assertEquals("simple2", result.getSimpleName());
        // primary non-empty namespace -> use primary's namespace
        assertEquals("nsPrimary", result.getNamespace());
    }

