    // Integration test with actual annotations (requires xml module)
    @Test
    public void testMergeWithActualAnnotations() throws Exception {
        // Simulate the scenario: @JacksonXmlProperty (empty defaults) and @JsonProperty with explicit values
        // We'll create a simple class with both annotations and use XmlMapper (which uses JacksonXmlAnnotationIntrospector)
        // and JacksonAnnotationIntrospector.
        // Since we cannot easily instantiate the introspectors directly, we rely on the mapper's behavior.
        // However, we can test PropertyName.merge directly.
        PropertyName fromXml = new PropertyName("", ""); // JacksonXmlProperty defaults
        PropertyName fromJson = new PropertyName("prop", "uri:ns1");
        PropertyName merged = PropertyName.merge(fromXml, fromJson);
        assertEquals("prop", merged.getSimpleName());
        assertEquals("uri:ns1", merged.getNamespace());

        // Reverse order: Json first, Xml second (Json higher precedence)
        merged = PropertyName.merge(fromJson, fromXml);
        assertEquals("prop", merged.getSimpleName());
        assertEquals("uri:ns1", merged.getNamespace());
    }

    @Test
    public void testPropertyNameMergeMethod() {
        // Test merge with null inputs
        assertNull(PropertyName.merge(null, null));
        PropertyName pn = new PropertyName("test", "ns");
        assertEquals(pn, PropertyName.merge(pn, null));
        assertEquals(pn, PropertyName.merge(null, pn));

        // Test merge with empty strings
        PropertyName empty1 = new PropertyName("", "");
        PropertyName nonEmpty = new PropertyName("simple", "namespace");
        PropertyName merged = PropertyName.merge(empty1, nonEmpty);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("namespace", merged.getNamespace());

        // Test merge with non-empty first, empty second
        merged = PropertyName.merge(nonEmpty, empty1);
        assertEquals(nonEmpty, merged);

        // Test merge with both non-empty: first takes precedence
        PropertyName other = new PropertyName("other", "otherNs");
        merged = PropertyName.merge(nonEmpty, other);
        assertEquals(nonEmpty, merged);

        // Test merge with same values returns same instance
        PropertyName same = new PropertyName("simple", "namespace");
        merged = PropertyName.merge(nonEmpty, same);
        assertSame(nonEmpty, merged); // should return first argument because identical

        // Test merge with first empty simple name but non-empty namespace
        PropertyName partial = new PropertyName("", "ns1");
        PropertyName full = new PropertyName("simple2", "ns2");
        merged = PropertyName.merge(partial, full);
        assertEquals("simple2", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
    }
}

