package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.json.JsonReadFeature;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.ser.std.ToStringSerializer;
import com.fasterxml.jackson.databind.deser.std.StringDeserializer;
import org.junit.Test;

import java.text.SimpleDateFormat;
import java.util.Locale;
import java.util.TimeZone;

import static org.junit.Assert.*;

public class ObjectMapperCopyWithTest {

    @Test
    public void testCopyWithWithDifferentJsonFactory() {
        // Create a configured ObjectMapper with JSON factory
        ObjectMapper original = new ObjectMapper();
        original.enable(SerializationFeature.INDENT_OUTPUT);
        original.enable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);
        original.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);

        // Add a custom module to ensure configuration is copied
        SimpleModule module = new SimpleModule("TestModule");
        module.addSerializer(String.class, ToStringSerializer.instance);
        module.addDeserializer(String.class, new StringDeserializer());
        original.registerModule(module);

        // Create a different factory
        JsonFactory customFactory = JsonFactory.builder()
                .enable(JsonReadFeature.ALLOW_UNQUOTED_FIELD_NAMES)
                .build();

        // Use the new copyWith method
        ObjectMapper copy = original.copyWith(customFactory);

        // Verify the factory is the one provided (not a copy)
        assertSame("Factory should be the provided instance", customFactory, copy.tokenStreamFactory());

        // Verify configuration is preserved
        assertTrue("Serialization feature should be preserved", 
                   copy.isEnabled(SerializationFeature.INDENT_OUTPUT));
        assertTrue("Deserialization feature should be preserved", 
                   copy.isEnabled(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY));
        assertFalse("Disabled feature should be preserved", 
                    copy.isEnabled(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES));

        // Verify modules are copied
        assertNotNull("Module should be present", copy.getRegisteredModuleIds());
        assertTrue("Should contain test module", copy.getRegisteredModuleIds().contains("TestModule"));

        // Verify the copy is independent
        original.disable(SerializationFeature.INDENT_OUTPUT);
        assertTrue("Copy should not be affected by changes to original", 
                   copy.isEnabled(SerializationFeature.INDENT_OUTPUT));

        // Verify factory is properly linked to the mapper
        assertSame("Factory should reference the mapper as codec", copy, customFactory.getCodec());
    }

    @Test
    public void testCopyWithWithNullFactory() {
        ObjectMapper original = new ObjectMapper();
        original.enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);

        // This should use the original's factory copy (not null)
        ObjectMapper copy = original.copyWith(null);

        // Factory should be a copy of original's factory
        assertNotSame("Factory should be a copy, not the same instance", 
                      original.tokenStreamFactory(), copy.tokenStreamFactory());
        assertNotNull("Factory should not be null", copy.tokenStreamFactory());

        // Configuration should be preserved
        assertTrue("Feature should be preserved", 
                   copy.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS));
    }

    @Test
    public void testCopyWithPreservesMixIns() {
        ObjectMapper original = new ObjectMapper();

        // Add a mix-in
        original.addMixIn(String.class, Number.class);

        JsonFactory newFactory = new JsonFactory();
        ObjectMapper copy = original.copyWith(newFactory);

        // Verify mix-in is preserved
        assertEquals("Mix-in should be preserved", 
                     Number.class, copy.findMixInClassFor(String.class));
    }

    @Test
    public void testCopyWithPreservesInjectableValues() {
        ObjectMapper original = new ObjectMapper();
        InjectableValues injectableValues = new InjectableValues.Std()
            .addValue("key", "value");
        original.setInjectableValues(injectableValues);

        JsonFactory newFactory = new JsonFactory();
        ObjectMapper copy = original.copyWith(newFactory);

        assertSame("InjectableValues should be preserved", 
                   injectableValues, copy.getInjectableValues());
    }

    @Test
    public void testCopyWithPreservesSubtypeResolver() {
        ObjectMapper original = new ObjectMapper();
        Object originalResolver = original.getSubtypeResolver();

        JsonFactory newFactory = new JsonFactory();
        ObjectMapper copy = original.copyWith(newFactory);

        assertNotSame("SubtypeResolver should be a copy", 
                      originalResolver, copy.getSubtypeResolver());
        assertNotNull("SubtypeResolver should not be null", copy.getSubtypeResolver());
    }

    @Test
    public void testCopyWithCreatesIndependentMapper() {
        ObjectMapper original = new ObjectMapper();
        original.enable(SerializationFeature.WRAP_ROOT_VALUE);

        JsonFactory newFactory = new JsonFactory();
        ObjectMapper copy = original.copyWith(newFactory);

        // Modify the copy
        copy.disable(SerializationFeature.WRAP_ROOT_VALUE);

        // Verify original is unchanged
        assertTrue("Original should still have feature enabled", 
                   original.isEnabled(SerializationFeature.WRAP_ROOT_VALUE));
        assertFalse("Copy should have feature disabled", 
                    copy.isEnabled(SerializationFeature.WRAP_ROOT_VALUE));
    }

    @Test
    public void testCopyWithDifferentFactoryTypes() {
        ObjectMapper original = new ObjectMapper();

        // Test with different factory implementations
        // Note: We can't test with SmileFactory and CBORFactory without adding dependencies
        // So we'll test with JsonFactory and a custom factory
        JsonFactory[] factories = {
            new JsonFactory(),
            JsonFactory.builder().build()
        };

        for (JsonFactory factory : factories) {
            ObjectMapper copy = original.copyWith(factory);
            assertSame("Factory should be the provided instance", factory, copy.tokenStreamFactory());
            assertSame("Factory should reference the mapper", copy, factory.getCodec());
        }
    }

    @Test
    public void testCopyWithPreservesTypeFactory() {
        ObjectMapper original = new ObjectMapper();
        com.fasterxml.jackson.databind.type.TypeFactory typeFactory = original.getTypeFactory().withModifier(null);
        original.setTypeFactory(typeFactory);

        JsonFactory newFactory = new JsonFactory();
        ObjectMapper copy = original.copyWith(newFactory);

        assertSame("TypeFactory should be preserved", typeFactory, copy.getTypeFactory());
    }

    @Test
    public void testCopyWithAfterConfigurationChanges() {
        ObjectMapper original = new ObjectMapper();

        // Make various configuration changes
        original.setDateFormat(new SimpleDateFormat("yyyy-MM-dd"));
        original.setLocale(Locale.FRENCH);
        original.setTimeZone(TimeZone.getTimeZone("GMT"));

        JsonFactory newFactory = new JsonFactory();
        ObjectMapper copy = original.copyWith(newFactory);

        // Verify configurations are preserved
        assertEquals("DateFormat should be preserved", 
                     original.getDateFormat(), copy.getDateFormat());

        // Use getSerializationConfig().getLocale() instead of getLocale()
        assertEquals("Locale should be preserved", 
                     original.getSerializationConfig().getLocale(), 
                     copy.getSerializationConfig().getLocale());

        // Use getSerializationConfig().getTimeZone() instead of getTimeZone()
        assertEquals("TimeZone should be preserved", 
                     original.getSerializationConfig().getTimeZone(), 
                     copy.getSerializationConfig().getTimeZone());
    }
}

