package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.Version;
import org.junit.Test;
import static org.junit.Assert.*;

public class AnnotationIntrospectorPairMergeTest {

    // Helper to create a simple introspector that returns a fixed PropertyName
    private static class FixedPropertyNameIntrospector extends AnnotationIntrospector {
        private final PropertyName name;
        FixedPropertyNameIntrospector(PropertyName name) {
            this.name = name;
        }
        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return name;
        }
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return name;
        }
        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return name;
        }
        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return name;
        }
        @Override
        public PropertyName findRenameByField(MapperConfig<?> config,
                AnnotatedField f, PropertyName implName) {
            return name;
        }
        @Override
        public Version version() {
            return Version.unknownVersion();
        }
    }

    // Introspector that returns null
    private static class NullIntrospector extends AnnotationIntrospector {
        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return null;
        }
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return null;
        }
        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return null;
        }
        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return null;
        }
        @Override
        public PropertyName findRenameByField(MapperConfig<?> config,
                AnnotatedField f, PropertyName implName) {
            return null;
        }
        @Override
        public Version version() {
            return Version.unknownVersion();
        }
    }

    // Introspector that returns USE_DEFAULT
    private static class UseDefaultIntrospector extends AnnotationIntrospector {
        @Override
        public PropertyName findWrapperName(Annotated ann) {
            return PropertyName.USE_DEFAULT;
        }
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return PropertyName.USE_DEFAULT;
        }
        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return PropertyName.USE_DEFAULT;
        }
        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return PropertyName.USE_DEFAULT;
        }
        @Override
        public PropertyName findRenameByField(MapperConfig<?> config,
                AnnotatedField f, PropertyName implName) {
            return PropertyName.USE_DEFAULT;
        }
        @Override
        public Version version() {
            return Version.unknownVersion();
        }
    }

    // Introspector that returns empty simple name (but not USE_DEFAULT)
    private static class EmptySimpleNameIntrospector extends AnnotationIntrospector {
        @Override
        public PropertyName findWrapperName(Annotated ann) {
