        // The xml introspector returns empty strings for local name and namespace,
        // while json introspector provides explicit values.
        // The merged PropertyName should have simple name "prop" and namespace "uri:ns1".

        // We'll use a mock setup because we don't have the actual xml introspector in core databind.
        // Create a custom introspector that mimics the xml introspector behavior for empty strings.
        AnnotationIntrospector xmlLike = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Simulate @JacksonXmlProperty(isAttribute=true) returning empty strings
                return new PropertyName("", "");
            }
            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospector jsonLike = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Simulate @JsonProperty(namespace="uri:ns1", value="prop")
                return PropertyName.construct("prop", "uri:ns1");
            }
            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(xmlLike, jsonLike);
        PropertyName result = pair.findNameForSerialization(null);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
