                new FixedPropertyNameIntrospector(PropertyName.construct("secondary")));
        assertEquals(PropertyName.construct("secondary"),
                pair.findRenameByField(null, null, null));

        // both null -> null
        pair = new AnnotationIntrospectorPair(new NullIntrospector(), new NullIntrospector());
        assertNull(pair.findRenameByField(null, null, null));
    }

    // Test merging with namespace
    @Test
    public void testMergeWithNamespace() {
        // primary has namespace, secondary has simple name
        PropertyName primary = PropertyName.construct(null, "ns1");
        PropertyName secondary = PropertyName.construct("simple", null);
        PropertyName merged = PropertyName.merge(primary, secondary);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // primary has simple name, secondary has namespace
        primary = PropertyName.construct("simple", null);
        secondary = PropertyName.construct(null, "ns2");
        merged = PropertyName.merge(primary, secondary);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());

        // primary empty simple name, secondary explicit simple name and namespace
        primary = PropertyName.construct("", "ns1");
        secondary = PropertyName.construct("explicit", "ns2");
        merged = PropertyName.merge(primary, secondary);
        assertEquals("explicit", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace()); // ns1 is non-empty, so kept

        // primary empty namespace, secondary explicit namespace
        primary = PropertyName.construct("simple", "");
        secondary = PropertyName.construct("simple", "ns2");
        merged = PropertyName.merge(primary, secondary);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());

        // both empty strings -> empty strings
        primary = PropertyName.construct("", "");
        secondary = PropertyName.construct("", "");
        merged = PropertyName.merge(primary, secondary);
        assertEquals("", merged.getSimpleName());
        assertEquals("", merged.getNamespace());
    }

    // Integration test with actual annotations (requires xml module)
    @Test
    public void testIntegrationWithXmlAndJsonAnnotations() throws Exception {
        // This test simulates the scenario described in the requirement:
        // @JacksonXmlProperty(isAttribute=true)  // handled by primary introspector (xml)
        // @JsonProperty(namespace="uri:ns1", value="prop") // handled by secondary introspector (json)
        // public int value;
        // The xml introspector returns empty strings for local name and namespace,
        // while json introspector provides explicit values.
        // The merged PropertyName should have simple name "prop" and namespace "uri:ns1".

        // We'll use a mock setup because we don't have the actual xml introspector in core databind.
        // Create a custom introspector that mimics the xml introspector behavior for empty strings.
        AnnotationIntrospector xmlLike = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Simulate @JacksonXmlProperty(isAttribute=true) returning empty strings
                return new PropertyName("", "");
            }
            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospector jsonLike = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                // Simulate @JsonProperty(namespace="uri:ns1", value="prop")
                return PropertyName.construct("prop", "uri:ns1");
            }
            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(xmlLike, jsonLike);
        PropertyName result = pair.findNameForSerialization(null);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
    }
